#include <sys/epoll.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/uaccess.h>

int handle_epoll_ctl(int epfd, int op, int fd, struct epoll_event __user *event) {
    struct epoll_event ep_event;
    if (copy_from_user(&ep_event, event, sizeof(struct epoll_event))) {
        return -EFAULT;
    }

    if (fd == epfd) {
        return -EINVAL;
    }

    int flags = fcntl(fd, F_GETFL);
    if (flags == -1 || (flags & O_ACCMODE) == O_WRONLY) {
        return -EBADF;
    }

    int ret = epoll_ctl(epfd, op, fd, &ep_event);
    if (ret < 0) {
        return ret;
    }

    return 0;
}

int epoll_ctl(int epfd, int op, int fd, struct epoll_event __user *event) {
    struct file *file, *f;
    struct epoll *ep;
    int error;

    error = -EINVAL;
    if (op != EPOLL_CTL_ADD && op != EPOLL_CTL_DEL && op != EPOLL_CTL_MOD)
        return error;

    file = fget(epfd);
    if (!file)
        return -EBADF;

    if (file->f_op != &eventpoll_fops) {
        fput(file);
        return -EINVAL;
    }

    ep = file->private_data;
    f = fget(fd);
    if (!f) {
        fput(file);
        return -EBADF;
    }

    if (f == file) {
        fput(f);
        fput(file);
        return -EINVAL;
    }

    if (op == EPOLL_CTL_DEL) {
        mutex_lock(&ep->mtx);
        error = ep_unregister_fd(ep, fd);
        mutex_unlock(&ep->mtx);
    } else {
        struct epoll_event *ep_event;
        error = -ENOMEM;
        ep_event = kmalloc(sizeof(*ep_event), GFP_KERNEL);
        if (!ep_event)
            goto error_fput;

        if (copy_from_user(ep_event, event, sizeof(*event))) {
            kfree(ep_event);
            goto error_fput;
        }

        mutex_lock(&ep->mtx);
        if (op == EPOLL_CTL_ADD)
            error = ep_register_fd(ep, fd, ep_event);
        else
            error = ep_modify_fd(ep, fd, ep_event);
        mutex_unlock(&ep->mtx);
        kfree(ep_event);
    }

error_fput:
    fput(f);
    fput(file);
    return error;
}

